<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Maze Discovery</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body {
    background: #0b1020;
    color: #d6e2ff;
    font-family: ui-sans-serif, system-ui, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
    min-height: 100%;
  }
  body {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 16px 12px 28px;
    gap: 12px;
  }
  h1 {
    font-size: 20px;
    font-weight: 650;
    letter-spacing: 0.04em;
    color: #9fd4ff;
  }
  .hud {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 16px 22px;
    width: min(540px, 100%);
    background: #141b33;
    border: 1px solid #2a3760;
    border-radius: 10px;
    padding: 10px 14px;
  }
  .stat {
    font-size: 15px;
    color: #9aa8cc;
  }
  .stat span {
    color: #f4f7ff;
    font-variant-numeric: tabular-nums;
    font-weight: 700;
  }
  #reset {
    appearance: none;
    border: 0;
    background: #2d6cdf;
    color: #fff;
    font-weight: 700;
    font-size: 14px;
    padding: 8px 16px;
    border-radius: 8px;
    cursor: pointer;
  }
  #reset:hover { background: #3b7af0; }
  #maze {
    width: 540px;
    height: 540px;
    max-width: 100%;
    background: #070b16;
    border: 1px solid #2a3760;
    border-radius: 10px;
    overflow: hidden;
  }
  #maze canvas {
    display: block;
    width: 100%;
    height: 100%;
  }
</style>
</head>
<body>
  <h1>Maze Discovery</h1>
  <div class="hud">
    <div class="stat">Completed: <span id="completed">0</span>/24</div>
    <div class="stat">Time: <span id="timer">0</span></div>
    <button id="reset" type="button">Reset</button>
  </div>
  <div id="maze"><canvas id="mazeCanvas" width="540" height="540"></canvas></div>
<script>
(function () {
  const ROWS = 15;
  const COLS = 15;
  const BOT_COUNT = 24;
  const DIRS = ['n', 'e', 's', 'w'];
  const DELTA = { n: [-1, 0], e: [0, 1], s: [1, 0], w: [0, -1] };
  const OPP = { n: 's', e: 'w', s: 'n', w: 'e' };
  const STEP_MS = 48;

  const canvas = document.getElementById('mazeCanvas');
  const ctx = canvas.getContext('2d');
  const completedEl = document.getElementById('completed');
  const timerEl = document.getElementById('timer');
  const resetBtn = document.getElementById('reset');

  let grid = [];
  let spawn = { r: 0, c: 0 };
  let exitCell = { r: ROWS - 1, c: COLS - 1 };
  let elapsed = 0;
  let finishedCount = 0;
  let autoPlay = true;
  const bots = [];

  let lerpFrom = [];
  let lerpT = 1;
  let lastFrame = 0;
  let acc = 0;

  function mulberry32(a) {
    return function () {
      a |= 0;
      a = a + 0x6D2B79F5 | 0;
      let t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  function shuffle(arr, rng) {
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(rng() * (i + 1));
      const tmp = a[i];
      a[i] = a[j];
      a[j] = tmp;
    }
    return a;
  }

  function allPermutations(items) {
    if (items.length <= 1) return [items.slice()];
    const out = [];
    for (let i = 0; i < items.length; i++) {
      const rest = items.slice(0, i).concat(items.slice(i + 1));
      const sub = allPermutations(rest);
      for (let k = 0; k < sub.length; k++) out.push([items[i]].concat(sub[k]));
    }
    return out;
  }

  function cellKey(r, c) { return r + ',' + c; }

  function edgeKey(r1, c1, r2, c2) {
    if (r1 < r2 || (r1 === r2 && c1 < c2)) return r1 + ',' + c1 + '-' + r2 + ',' + c2;
    return r2 + ',' + c2 + '-' + r1 + ',' + c1;
  }

  function generateMaze(rng) {
    const walls = [];
    const seen = [];
    for (let r = 0; r < ROWS; r++) {
      walls[r] = [];
      seen[r] = [];
      for (let c = 0; c < COLS; c++) {
        walls[r][c] = { n: true, e: true, s: true, w: true };
        seen[r][c] = false;
      }
    }
    const dirObjs = [
      { d: 'n', dr: -1, dc: 0 },
      { d: 'e', dr: 0, dc: 1 },
      { d: 's', dr: 1, dc: 0 },
      { d: 'w', dr: 0, dc: -1 }
    ];
    const sr = Math.floor(rng() * ROWS);
    const sc = Math.floor(rng() * COLS);
    const stack = [[sr, sc]];
    seen[sr][sc] = true;
    while (stack.length) {
      const cur = stack[stack.length - 1];
      const r = cur[0], c = cur[1];
      const opts = [];
      const order = shuffle(dirObjs, rng);
      for (let i = 0; i < order.length; i++) {
        const o = order[i];
        const nr = r + o.dr, nc = c + o.dc;
        if (nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS && !seen[nr][nc]) {
          opts.push(o);
        }
      }
      if (!opts.length) {
        stack.pop();
      } else {
        const o = opts[0];
        const nr = r + o.dr, nc = c + o.dc;
        walls[r][c][o.d] = false;
        walls[nr][nc][OPP[o.d]] = false;
        seen[nr][nc] = true;
        stack.push([nr, nc]);
      }
    }
    return walls;
  }

  function farthestCell(sr, sc) {
    const q = [[sr, sc, 0]];
    const seen = {};
    seen[cellKey(sr, sc)] = true;
    let best = { r: sr, c: sc, d: 0 };
    let qi = 0;
    while (qi < q.length) {
      const cur = q[qi++];
      if (cur[2] > best.d) best = { r: cur[0], c: cur[1], d: cur[2] };
      const w = grid[cur[0]][cur[1]];
      for (let i = 0; i < 4; i++) {
        const d = DIRS[i];
        if (w[d]) continue;
        const nr = cur[0] + DELTA[d][0];
        const nc = cur[1] + DELTA[d][1];
        const k = cellKey(nr, nc);
        if (seen[k]) continue;
        seen[k] = true;
        q.push([nr, nc, cur[2] + 1]);
      }
    }
    return best;
  }

  function makeBot(r, c, dirOrder, color) {
    const k = cellKey(r, c);
    return {
      r: r,
      c: c,
      path: [{ r: r, c: c }],
      deadEnds: [],
      finishTick: null,
      dirOrder: dirOrder,
      color: color,
      stack: [{ r: r, c: c }],
      visited: Object.create(null),
      deadSet: Object.create(null),
      edges: Object.create(null),
      _hue: color
    };
  }

  function markDead(bot, r, c) {
    const k = cellKey(r, c);
    if (bot.deadSet[k]) return;
    if (r === exitCell.r && c === exitCell.c) return;
    bot.deadSet[k] = true;
    bot.deadEnds.push({ r: r, c: c });
  }

  function moveBot(bot) {
    if (bot.finishTick !== null) return;
    if (bot.r === exitCell.r && bot.c === exitCell.c) return;

    const walls = grid[bot.r][bot.c];
    let choice = null;
    for (let i = 0; i < bot.dirOrder.length; i++) {
      const d = bot.dirOrder[i];
      if (walls[d]) continue;
      const nr = bot.r + DELTA[d][0];
      const nc = bot.c + DELTA[d][1];
      if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS) continue;
      const ek = edgeKey(bot.r, bot.c, nr, nc);
      if ((bot.edges[ek] || 0) >= 2) continue;
      const nk = cellKey(nr, nc);
      if (bot.deadSet[nk]) continue;
      if (!bot.visited[nk]) {
        choice = { r: nr, c: nc, forward: true };
        break;
      }
    }

    if (!choice) {
      markDead(bot, bot.r, bot.c);
      if (bot.stack.length > 1) {
        bot.stack.pop();
        const parent = bot.stack[bot.stack.length - 1];
        choice = { r: parent.r, c: parent.c, forward: false };
      } else {
        return;
      }
    }

    const ek = edgeKey(bot.r, bot.c, choice.r, choice.c);
    bot.edges[ek] = (bot.edges[ek] || 0) + 1;
    bot.r = choice.r;
    bot.c = choice.c;
    bot.path.push({ r: bot.r, c: bot.c });
    const nk = cellKey(bot.r, bot.c);
    if (!bot.visited[nk]) bot.visited[nk] = true;
    if (choice.forward) bot.stack.push({ r: bot.r, c: bot.c });
  }

  function updateHud() {
    completedEl.textContent = String(finishedCount);
    timerEl.textContent = String(elapsed);
  }

  function tick(n) {
    if (n === undefined || n === null) n = 1;
    n = Number(n);
    if (!isFinite(n) || n <= 0) return;
    n = Math.floor(n);
    for (let i = 0; i < n; i++) {
      if (finishedCount >= BOT_COUNT) break;
      for (let b = 0; b < bots.length; b++) {
        const bot = bots[b];
        if (bot.finishTick !== null) continue;
        moveBot(bot);
        if (bot.r === exitCell.r && bot.c === exitCell.c) {
          bot.finishTick = elapsed + 1;
          finishedCount++;
        }
      }
      elapsed++;
    }
    lerpT = 1;
    lerpFrom = bots.map(function (bot) { return { r: bot.r, c: bot.c }; });
    updateHud();
  }

  function reset(seed) {
    let s;
    if (typeof seed === 'number' && isFinite(seed)) {
      s = seed >>> 0;
      autoPlay = false;
    } else {
      s = (Math.random() * 0x100000000) >>> 0;
      autoPlay = true;
    }
    const rng = mulberry32(s);
    grid = generateMaze(rng);
    spawn = {
      r: Math.floor(rng() * ROWS),
      c: Math.floor(rng() * COLS)
    };
    const far = farthestCell(spawn.r, spawn.c);
    exitCell = { r: far.r, c: far.c };
    if (exitCell.r === spawn.r && exitCell.c === spawn.c) {
      exitCell = { r: ROWS - 1 - spawn.r, c: COLS - 1 - spawn.c };
    }

    const perms = shuffle(allPermutations(DIRS), rng);
    bots.length = 0;
    for (let i = 0; i < BOT_COUNT; i++) {
      const hue = (i * 360 / BOT_COUNT);
      const bot = makeBot(spawn.r, spawn.c, perms[i], hue);
      bot.visited[cellKey(spawn.r, spawn.c)] = true;
      bots.push(bot);
    }
    elapsed = 0;
    finishedCount = 0;
    if (spawn.r === exitCell.r && spawn.c === exitCell.c) {
      for (let i = 0; i < bots.length; i++) {
        bots[i].finishTick = 0;
      }
      finishedCount = BOT_COUNT;
    }
    lerpFrom = bots.map(function (bot) { return { r: bot.r, c: bot.c }; });
    lerpT = 1;
    acc = 0;
    updateHud();
    draw(1);
  }

  function resizeCanvas() {
    const box = document.getElementById('maze').getBoundingClientRect();
    const w = Math.max(400, Math.floor(box.width));
    const h = Math.max(400, Math.floor(box.height));
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.floor(w * dpr);
    canvas.height = Math.floor(h * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    canvas._cssW = w;
    canvas._cssH = h;
  }

  function draw(t) {
    const w = canvas._cssW || 540;
    const h = canvas._cssH || 540;
    const pad = 10;
    const cell = Math.min((w - pad * 2) / COLS, (h - pad * 2) / ROWS);
    const ox = (w - cell * COLS) / 2;
    const oy = (h - cell * ROWS) / 2;
    const tt = t < 0 ? 0 : t > 1 ? 1 : t;
    const e = tt * tt * (3 - 2 * tt);

    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = '#070b16';
    ctx.fillRect(0, 0, w, h);

    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const x = ox + c * cell;
        const y = oy + r * cell;
        const isExit = r === exitCell.r && c === exitCell.c;
        const isSpawn = r === spawn.r && c === spawn.c;
        if (isExit) ctx.fillStyle = '#1d3b28';
        else if (isSpawn) ctx.fillStyle = '#243056';
        else ctx.fillStyle = ((r + c) & 1) ? '#10182c' : '#0e1526';
        ctx.fillRect(x, y, cell + 0.5, cell + 0.5);
      }
    }

    const ex = ox + (exitCell.c + 0.5) * cell;
    const ey = oy + (exitCell.r + 0.5) * cell;
    ctx.beginPath();
    ctx.arc(ex, ey, cell * 0.28, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(70, 210, 130, 0.28)';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = '#4ee39a';
    ctx.stroke();

    ctx.strokeStyle = '#86b7ff';
    ctx.lineWidth = Math.max(2.5, cell * 0.08);
    ctx.lineCap = 'square';
    ctx.beginPath();
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const x = ox + c * cell;
        const y = oy + r * cell;
        const walls = grid[r][c];
        if (walls.n) { ctx.moveTo(x, y); ctx.lineTo(x + cell, y); }
        if (walls.w) { ctx.moveTo(x, y); ctx.lineTo(x, y + cell); }
        if (r === ROWS - 1 && walls.s) { ctx.moveTo(x, y + cell); ctx.lineTo(x + cell, y + cell); }
        if (c === COLS - 1 && walls.e) { ctx.moveTo(x + cell, y); ctx.lineTo(x + cell, y + cell); }
      }
    }
    ctx.stroke();

    for (let i = 0; i < bots.length; i++) {
      const bot = bots[i];
      const from = lerpFrom[i] || bot;
      const rr = from.r + (bot.r - from.r) * e;
      const cc = from.c + (bot.c - from.c) * e;
      const ang = (i / BOT_COUNT) * Math.PI * 2;
      const spread = cell * 0.16;
      const px = ox + (cc + 0.5) * cell + Math.cos(ang) * spread;
      const py = oy + (rr + 0.5) * cell + Math.sin(ang) * spread;
      const rad = Math.max(3.2, cell * 0.13);
      ctx.beginPath();
      ctx.arc(px, py, rad, 0, Math.PI * 2);
      ctx.fillStyle = 'hsl(' + bot._hue + ', 85%, 60%)';
      ctx.fill();
      ctx.lineWidth = 1.4;
      ctx.strokeStyle = bot.finishTick !== null ? '#fff' : 'rgba(255,255,255,0.55)';
      ctx.stroke();
    }
  }

  function frame(ts) {
    requestAnimationFrame(frame);
    if (!lastFrame) lastFrame = ts;
    const dt = Math.min(80, ts - lastFrame);
    lastFrame = ts;
    if (autoPlay && finishedCount < BOT_COUNT) {
      acc += dt;
      if (acc >= STEP_MS) {
        acc -= STEP_MS;
        lerpFrom = bots.map(function (bot) { return { r: bot.r, c: bot.c }; });
        tick(1);
        lerpT = 0;
      }
    } else if (finishedCount >= BOT_COUNT) {
      lerpT = 1;
    }
    if (lerpT < 1) {
      lerpT = Math.min(1, lerpT + dt / STEP_MS);
    }
    draw(lerpT);
  }

  window.game = {
    tick: tick,
    reset: reset,
    get elapsed() { return elapsed; },
    get size() { return { rows: ROWS, cols: COLS }; },
    get spawn() { return { r: spawn.r, c: spawn.c }; },
    get exit() { return { r: exitCell.r, c: exitCell.c }; },
    walls: function (r, c) {
      const w = grid[r][c];
      return { n: w.n, e: w.e, s: w.s, w: w.w };
    },
    get bots() { return bots; }
  };

  resetBtn.addEventListener('click', function () { reset(); });
  window.addEventListener('resize', function () { resizeCanvas(); draw(lerpT); });

  resizeCanvas();
  reset();
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
